// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "Token", "TKN"); }
    function testRegression_property() public {
        c.burn(100);
        uint256 ownerBalance = c.balanceOf(address(this));
        uint256 totalSupply = c.totalSupply();
        assertTrue(ownerBalance + totalSupply == 1800);
    }
}
